"""The run report (coal.report/1) against docs/report.schema.json, for reports freshly generated by BOTH engines.

Every scenario below runs through the Python engine (in-process) and, when build/coal-cpp (COAL_CPP_BIN) is built,
through the C++ engine; each report must validate against the JSON Schema, and the two engines' reports must be
equal apart from engine, runtime_seconds and the report path in command_line. docs/report-schema.md's complete example and
tests/report_example.json (the same report) are validated too.

Validation uses the `jsonschema` package when it is importable (draft 2020-12), and always the small dependency-free
validator below (the keywords the schema uses: type, const, enum, pattern, minimum, minItems, required, properties,
items, $ref to #/$defs, allOf, if/then/else), so the check also runs where jsonschema is not installed."""
from __future__ import annotations

import io
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))
from coal.cli import main as coal_main  # noqa: E402

SCHEMA_PATH = ROOT / "docs" / "report.schema.json"
DOC_PATH = ROOT / "docs" / "report-schema.md"
EXAMPLE_PATH = ROOT / "tests" / "report_example.json"
EXAMPLES = ROOT / "examples"

try:
    import jsonschema  # type: ignore
except ImportError:  # pragma: no cover - depends on the environment
    jsonschema = None


def cpp_binary() -> Path | None:
    p = Path(os.environ.get("COAL_CPP_BIN", ROOT / "build" / "coal-cpp"))
    if not p.is_absolute():
        p = ROOT / p
    for cand in (p, p.with_suffix(".exe"), p.parent / "Release" / (p.name + ".exe")):
        if cand.is_file() and (os.name != "nt" or cand.suffix.lower() == ".exe"):
            return cand
    return None


# ------------------------------------------------------------------ a small JSON Schema validator

class SchemaError(AssertionError):
    pass


_TYPES = {"object": dict, "array": list, "string": str, "boolean": bool, "null": type(None)}


def _is_type(value, name: str) -> bool:
    if name == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if name == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    return isinstance(value, _TYPES[name])


def _resolve(ref: str, root: dict) -> dict:
    assert ref.startswith("#/"), ref
    node = root
    for part in ref[2:].split("/"):
        node = node[part]
    return node


def _passes(value, schema: dict, root: dict) -> bool:
    try:
        validate(value, schema, root)
        return True
    except SchemaError:
        return False


def validate(value, schema: dict, root: dict | None = None, path: str = "$") -> None:
    """Raise SchemaError if `value` does not satisfy `schema` (the subset of draft 2020-12 the report schema uses)."""
    root = schema if root is None else root
    if "$ref" in schema:
        validate(value, _resolve(schema["$ref"], root), root, path)
    if "type" in schema:
        types = schema["type"] if isinstance(schema["type"], list) else [schema["type"]]
        if not any(_is_type(value, t) for t in types):
            raise SchemaError(f"{path}: {value!r} is not of type {types}")
    if "const" in schema and value != schema["const"]:
        raise SchemaError(f"{path}: {value!r} != {schema['const']!r}")
    if "enum" in schema and value not in schema["enum"]:
        raise SchemaError(f"{path}: {value!r} not in {schema['enum']}")
    if "pattern" in schema and isinstance(value, str) and not re.search(schema["pattern"], value):
        raise SchemaError(f"{path}: {value!r} does not match {schema['pattern']}")
    if "minimum" in schema and _is_type(value, "number") and value < schema["minimum"]:
        raise SchemaError(f"{path}: {value!r} < {schema['minimum']}")
    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            raise SchemaError(f"{path}: fewer than {schema['minItems']} items")
        if "items" in schema:
            for i, item in enumerate(value):
                validate(item, schema["items"], root, f"{path}[{i}]")
    if isinstance(value, dict):
        for key in schema.get("required", ()):
            if key not in value:
                raise SchemaError(f"{path}: missing required key {key!r}")
        for key, sub in schema.get("properties", {}).items():
            if key in value:
                validate(value[key], sub, root, f"{path}.{key}")
    for i, sub in enumerate(schema.get("allOf", ())):
        validate(value, sub, root, f"{path}<allOf {i}>")
    if "if" in schema:
        branch = "then" if _passes(value, schema["if"], root) else "else"
        if branch in schema:
            validate(value, schema[branch], root, f"{path}<{branch}>")


# ------------------------------------------------------------------ generating reports

def run_python(d: Path, args: list[str]) -> int:
    out, err = io.StringIO(), io.StringIO()
    cwd = os.getcwd()
    os.chdir(d)
    try:
        with redirect_stdout(out), redirect_stderr(err):
            try:
                return coal_main(args)
            except SystemExit as e:
                return int(e.code or 0)
    finally:
        os.chdir(cwd)


def run_cpp(d: Path, args: list[str]) -> int:
    return subprocess.run([str(cpp_binary()), *args], cwd=d, capture_output=True, timeout=120).returncode


def write(d: Path, pep: list[tuple[str, str]], nuc: list[tuple[str, str]]) -> None:
    (d / "pep.fa").write_text("".join(f">{i}\n{s}\n" for i, s in pep))
    (d / "nuc.fa").write_text("".join(f">{i}\n{s}\n" for i, s in nuc))


def copy_example(d: Path, name: str) -> None:
    for f in ("protein.aln.fasta", "dna.fasta"):
        shutil.copy(EXAMPLES / name / f, d / f)


EX = ["protein.aln.fasta", "dna.fasta"]
# a 30-residue gene whose column 11 (H) has the codon GAT (D): PAL2NAL's fallback writes it with one mismatch warning
PROT = "MFWDKESRSPHESAPQYARKIWEMAAAVAP"
GOOD = "ATGTTCTGGGACAAAGAAAGCAGAAGCCCACACGAAAGCGCACCACAATACGCAAGAAAAATATGGGAAATGGCAGCAGCAGTAGCACCA"
BAD = GOOD[:30] + "GAT" + GOOD[33:]
# name -> (how to set the folder up, the command line without --report; the expected exit code)
SCENARIOS = {
    "keep_going": (lambda d: copy_example(d, "one_broken_gene"), [*EX, "--keep-going", "-o", "codon.fasta"], 2),
    "aborted": (lambda d: copy_example(d, "one_broken_gene"), [*EX, "-o", "out.fa"], 1),
    "wrong_code": (lambda d: copy_example(d, "mito"), [*EX, "-o", "out.fa"], 0),
    "nomismatch_codon": (lambda d: copy_example(d, "mito"), [*EX, "-nomismatch", "-output", "paml", "-o", "o.paml"], 0),
    "normalised": (lambda d: copy_example(d, "messy_ids"), [*EX, "-o", "out.fa"], 0),
    "clean_stdout": (lambda d: copy_example(d, "clean"), EX, 0),
    "count_mismatch": (lambda d: write(d, [("a", "MK"), ("b", "MK")], [("a", "ATGAAA")]), ["pep.fa", "nuc.fa"], 1),
    "partial_order": (lambda d: write(d, [("a", PROT), ("b", PROT)], [("a", GOOD), ("c", BAD)]),
                      ["pep.fa", "nuc.fa", "-o", "out.fa"], 0),
    "strict_refused": (lambda d: write(d, [("a", PROT), ("b", PROT)], [("a", GOOD), ("c", BAD)]),
                       ["pep.fa", "nuc.fa", "--strict", "-o", "out.fa"], 1),
    "unrelated_flagged": (lambda d: write(d, [("a", PROT)], [("a", "ATG" + "CCA" * 29)]),
                          ["pep.fa", "nuc.fa", "-o", "out.fa"], 0),
    "unknown_aa": (lambda d: write(d, [("a", "MUK")], [("a", "ATGTGAAAA")]), ["pep.fa", "nuc.fa", "-o", "out.fa"], 0),
}


def generate(engine: str, name: str, tmp: Path) -> tuple[int, dict]:
    setup, args, _ = SCENARIOS[name]
    d = tmp / f"{engine}_{name}"
    d.mkdir()
    setup(d)
    rc = (run_python if engine == "py" else run_cpp)(d, [*args, "--report", "report.json"])
    return rc, json.loads((d / "report.json").read_text(encoding="utf-8"))


def comparable(rep: dict) -> dict:
    """The report without the two fields that differ between the engines (the engine's name and its run time)."""
    rep = dict(rep)
    rep.pop("runtime_seconds", None)
    rep.pop("engine", None)
    return rep


class TestReportSchema(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
        cls.tmp = Path(tempfile.mkdtemp())
        cls.ref = cls.tmp / "ref"  # the Python reports the C++ ones are compared with
        cls.ref.mkdir()

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    def check(self, rep: dict, what: str) -> None:
        try:
            validate(rep, self.schema)
        except SchemaError as e:
            self.fail(f"{what}: {e}")
        if jsonschema is not None:
            jsonschema.Draft202012Validator.check_schema(self.schema)
            errors = sorted(jsonschema.Draft202012Validator(self.schema).iter_errors(rep), key=str)
            self.assertEqual(errors, [], f"{what}: " + "; ".join(e.message for e in errors))

    def test_schema_is_draft_2020_12(self):
        self.assertEqual(self.schema["$schema"], "https://json-schema.org/draft/2020-12/schema")
        self.assertEqual(self.schema["properties"]["schema"]["const"], "coal.report/1")

    def test_validator_rejects_bad_reports(self):
        """The dependency-free validator is not a no-op."""
        good = json.loads(EXAMPLE_PATH.read_text(encoding="utf-8"))
        for change, msg in (
            (lambda r: r.pop("summary"), "missing required"),
            (lambda r: r.__setitem__("schema", "coal.report/2"), "!="),
            (lambda r: r["summary"].__setitem__("pairing", "by_name"), "not in"),
            (lambda r: r["sequences"][0].__setitem__("status", "fine"), "not in"),
            (lambda r: r["sequences"][13]["messages"].append({"code": "mismatch", "text": "x"}), "missing required"),
            (lambda r: r["sequences"][13]["messages"].append({"code": "not_reached"}), "missing required"),
            (lambda r: r["inputs"][0].__setitem__("sha256", "xyz"), "does not match"),
            (lambda r: r.__setitem__("exit_code", 3), "not in"),
        ):
            bad = json.loads(json.dumps(good))
            change(bad)
            with self.assertRaises(SchemaError, msg=msg) as cm:
                validate(bad, self.schema)
            self.assertIn(msg, str(cm.exception))

    def test_python_reports_validate(self):
        for name, (_, _, rc_expected) in SCENARIOS.items():
            with self.subTest(scenario=name):
                rc, rep = generate("py", name, self.tmp)
                self.assertEqual(rc, rc_expected)
                self.assertEqual(rep["exit_code"], rc)
                self.check(rep, f"python {name}")

    def test_cpp_reports_validate_and_equal_python(self):
        if cpp_binary() is None:
            self.skipTest("coal-cpp not built (COAL_CPP_BIN)")
        for name, (_, _, rc_expected) in SCENARIOS.items():
            with self.subTest(scenario=name):
                rc, cpp = generate("cpp", name, self.tmp)
                self.assertEqual(rc, rc_expected)
                self.check(cpp, f"coal-cpp {name}")
                _, py = generate("py", name, self.ref)
                self.assertEqual((cpp["engine"], py["engine"]), ("coal-cpp", "coal-python"))
                self.assertEqual(comparable(cpp), comparable(py), f"{name}: the C++ and Python reports differ")

    def test_json_option_is_the_same_report(self):
        d = self.tmp / "json_opt"
        d.mkdir()
        copy_example(d, "one_broken_gene")
        out = io.StringIO()
        cwd = os.getcwd()
        os.chdir(d)
        try:
            with redirect_stdout(out), redirect_stderr(io.StringIO()):
                rc = coal_main([*EX, "--keep-going", "-o", "out.fa", "--json", "--report", "r.json"])
        finally:
            os.chdir(cwd)
        self.assertEqual(rc, 2)
        printed = json.loads(out.getvalue())
        written = json.loads((d / "r.json").read_text(encoding="utf-8"))
        self.check(printed, "--json")
        self.assertEqual(comparable(printed), comparable(written))

    def test_example_file_and_doc_example(self):
        """tests/report_example.json is a real one_broken_gene --keep-going report, validates, and is the complete
        example shown in docs/report-schema.md."""
        ex = json.loads(EXAMPLE_PATH.read_text(encoding="utf-8"))
        self.check(ex, "tests/report_example.json")
        self.assertEqual(ex["command"], "coal protein.aln.fasta dna.fasta --keep-going -o codon.fasta")
        self.assertEqual([s["status"] for s in ex["sequences"]].count("failed"), 1)
        doc = DOC_PATH.read_text(encoding="utf-8")
        m = re.search(r"```json\n(\{\n \"schema\": \"coal.report/1\".*?\n\})\n```", doc, re.S)
        self.assertIsNotNone(m, "docs/report-schema.md has no complete example report")
        self.assertEqual(json.loads(m.group(1)), ex, "the example in docs/report-schema.md is not tests/report_example.json")
        # the example is what the engine writes today (apart from its runtime)
        (self.tmp / "doc").mkdir(exist_ok=True)
        _, fresh = generate("py", "keep_going", self.tmp / "doc")
        self.assertEqual(comparable(fresh), comparable(ex),
                         "tests/report_example.json is stale: regenerate it (see docs/report-schema.md)")

    def test_doc_lists_every_code(self):
        """Every status, pairing mode, hint code and message code the engine can emit is in docs/report-schema.md."""
        from coal import report as r
        doc = DOC_PATH.read_text(encoding="utf-8")
        for word in (*r.STATUSES, "id", "normalised", "order", "partial_id_match", "normalised_ids", "id_mismatch",
                     "genetic_code", "mismatch", "unknown_aa", "warning", "suspect_unrelated", "suspect_position",
                     "no_anchor", "suspect_pairing", "possible_frameshift", "frameshift", "missing_dna",
                     "inconsistent", "not_written", "not_reached", "invalid_protein", "empty", "count_mismatch",
                     "row_lengths", "no_sequences", "file_error", "input_format", "all_failed", "resume_mismatch",
                     "stopped", "columns_removed_ambiguous", "resumed_from", "start_codon", "end_column"):
            self.assertRegex(doc, rf"`{re.escape(word)}[`:]", f"docs/report-schema.md does not mention `{word}`")


if __name__ == "__main__":
    unittest.main()
